import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem93 nao inventa compatibilidade geracao ou reparo e preserva operacao',()=>{for(const [id,titulo] of [['mhz9cN2MnCkxuSW5OPlv','Pistola Fixação Finca Pino Ação Direta'],['mlMLB1921632393','Pc Gamer Completo I7 Gtx1650 Ssd120 Hd1tb 16gb Fonte 750w'],['mlMLB2088799901','Kit Reparo Pneu Tubeless Para Bike Bicileta']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/fixação garantida|60 FPS|vendedor oficial|reparo definitivo/i);if(id==='mlMLB1921632393')assert.doesNotMatch(x.comentario,/Tarjeta gráfica|Capacidad del disco|\bi7-\d+/);}});
